<?php
$id=max(0,(int)($_GET['id']??0));$invoice=row("SELECT * FROM documents WHERE id=? AND kind='invoice'",[$id]);if(!$invoice){emptyState('Facture introuvable.','Ouvrez une facture pour préparer un avoir.','Documents',url('documents'));return;}
$position=invoiceCreditPosition($invoice);$s=$position['snapshot'];$financial=paymentSummary((int)$invoice['order_id']);
heading('CORRECTION DE FACTURE','Préparer un avoir.',$invoice['number'].' · '.$s['client']['company']);
?><div class="document-actions"><a class="btn secondary" href="<?=e(url('document',['id'=>$id]))?>">← Facture originale</a></div><section class="panel padded"><p>Choisissez les quantités à créditer sur les lignes de la facture. Prix, remises, TVA et coordonnées proviennent du document original.</p><p class="small muted">Les montants sont répartis au centime selon les quantités cumulées. Le dernier reliquat reprend les centimes restants. Aucun retour en stock ni remboursement automatique.</p>
<?php if($financial['credited']>=cents($invoice['total'])):?><div class="notice info">Cette facture est intégralement créditée.</div><?php else:?><form method="post" id="credit-form" data-confirm="Émettre définitivement cet avoir ? Les montants et la facture d’origine seront conservés."><?=csrf()?><input type="hidden" name="action" value="credit_issue"><input type="hidden" name="invoice_id" value="<?=$id?>"><input type="hidden" name="request_key" value="<?=e(($_POST['action']??'')==='credit_issue'?($_POST['request_key']??''):bin2hex(random_bytes(32)))?>"><input type="hidden" name="position_key" value="<?=e($position['position_key'])?>">
<div class="table-scroll"><table><thead><tr><th>LIGNE D’ORIGINE</th><th>FACTURÉ</th><th>DÉJÀ CRÉDITÉ</th><th>DISPONIBLE</th><th>À CRÉDITER</th><th class="numeric">HT / TVA</th></tr></thead><tbody><?php foreach($position['items'] as $n=>$item):$left=$position['available'][$n];?><tr data-credit-line data-whole="<?=e(decimalInt($item['quantity'],3,6))?>" data-used="<?=$position['used'][$n]?>" data-net="<?=$item['subtotal']?>" data-tax="<?=$item['tax']?>"><td><strong><?=e($item['designation'])?></strong><small class="subline"><?=e(money($item['unit_price']))?> HT · remise <?=e($item['discount_rate'])?> % · TVA <?=e($item['tax_rate'])?> %</small></td><td><?=e($item['quantity'].' '.$item['unit'])?></td><td><?=e(decimalString($position['used'][$n],3))?></td><td><?=e(decimalString($left,3))?></td><td><label><span class="sr-only">Quantité à créditer · <?=e($item['designation'])?></span><input name="credit_qty[<?=$n?>]" type="number" step="0.001" min="0" max="<?=e(decimalString($left,3))?>" value="<?=e($_POST['credit_qty'][$n]??'0')?>" <?=$left?'':'readonly'?> required data-credit-qty></label></td><td class="numeric"><span data-credit-net>0,00 DH</span><small class="subline" data-credit-tax>0,00 DH</small></td></tr><?php endforeach?></tbody></table></div>
<div class="finance-summary"><div><span>HT à déduire</span><strong data-credit-total-net>0,00 DH</strong></div><div><span>TVA à déduire</span><strong data-credit-total-tax>0,00 DH</strong></div><div><span>Total de l’avoir TTC</span><strong data-credit-total>0,00 DH</strong></div></div><p role="status" aria-live="polite" id="credit-estimate-status"></p><div class="form-stack"><label>Motif de l’avoir *<textarea name="reason" maxlength="1000" required rows="3"><?=e($_POST['reason']??'')?></textarea></label><label><input type="checkbox" name="issue_confirmed" value="1" required> J’ai vérifié les quantités et les montants, je confirme l’émission définitive.</label><button class="btn primary">Émettre l’avoir</button></div></form><?php endif?></section>
